interface LanguageContextValue {
  language: Language;
  setLanguage: (language: Language) => void;
  t: (text: string, values?: Record<string, string | number>) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>('es');

  useEffect(() => {
    const savedLanguage = window.localStorage.getItem(LANGUAGE_KEY);
    if (savedLanguage && Object.prototype.hasOwnProperty.call(translations, savedLanguage)) {
      const timeoutId = window.setTimeout(() => setLanguageState(savedLanguage as Language), 0);
      return () => window.clearTimeout(timeoutId);
    }
  }, []);

  useEffect(() => {
    document.documentElement.lang = language;
    document.querySelector('meta[name="description"]')?.setAttribute('content', localizedMetadata[language].description);
  }, [language]);

  const setLanguage = (nextLanguage: Language) => {
    window.localStorage.setItem(LANGUAGE_KEY, nextLanguage);
    setLanguageState(nextLanguage);
  };

  const t = (text: string, values?: Record<string, string | number>) => {
    const translated = uiTranslations[text]?.[language] ?? translations[language][text] ?? text;
    return translated.replace(/\{(\w+)\}/g, (placeholder, key: string) =>
      String(values?.[key] ?? placeholder)
    );
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const context = useContext(LanguageContext);
  if (!context) {
    throw new Error('useLanguage debe usarse dentro de LanguageProvider');
  }
  return context;
}